    const canonical=Object.fromEntries(baseExercises.map(e=>[e.id,e]));
    s.exercises=s.exercises.map(e=>{const c=canonical[e.id];if(!c)return e;return {...e,name:c.name,group:c.group,equipment:c.equipment,active:c.active===false?false:e.active};});
    const removedIds=new Set(['e10','e21']);
    if(Array.isArray(s.savedPlans))s.savedPlans=s.savedPlans.map(p=>({...p,ids:(p.ids||[]).filter(id=>!removedIds.has(id))}));
    if(s.activeWorkout?.ids)s.activeWorkout.ids=s.activeWorkout.ids.filter(id=>!removedIds.has(id));
    if(Array.isArray(s.coachPlan?.days))s.coachPlan.days=s.coachPlan.days.map(p=>({...p,ids:(p.ids||[]).filter(id=>!removedIds.has(id))}));
