  return `<div class="exvisual ${size}" title="${label}"><svg viewBox="0 0 92 68" role="img" aria-label="Animierte Ausführung: ${label}" preserveAspectRatio="xMidYMid meet">${body}</svg><span>Bewegung</span></div>`;
