function worldProgress(){return (state.workoutHistory||[]).length+Object.keys(state.bossWins||{}).length*2+Math.floor((state.knowledge?.xp||0)/300)}
function worldUnlocked(n){return worldProgress()>=n.need}
function unlockedWorldIndex(){let x=0;worldNodes.forEach((n,i)=>{if(worldUnlocked(n))x=i});return x}
function charStats(){const hist=state.workoutHistory||[],loads=muscleLoad(),pull=loads.Rücken+loads.Arme,push=loads.Brust+loads.Schultern,legs=loads.Beine+loads.Gesäß,core=loads.Core;return {Kraft:Math.min(99,10+Math.round((pull+push+legs)/3)),Ausdauer:Math.min(99,10+hist.length*2),Core:Math.min(99,10+core*2),Balance:Math.min(99,10+Object.values(state.skillProgress||{}).reduce((a,b)=>a+Number(b||0),0)),Wissen:Math.min(99,10+Math.round((state.knowledge?.xp||0)/25))}}
function recoveryScores(){const l=muscleLoad(),map={Brust:l.Brust,Rücken:l.Rücken,Beine:l.Beine,Schultern:l.Schultern,Arme:l.Arme,Core:l.Core,Gesäß:l.Gesäß};return Object.fromEntries(Object.entries(map).map(([k,v])=>[k,Math.max(0,100-v*5)]))}
function nextBoss(){return worldNodes.find(n=>n.type==='boss'&&worldUnlocked(n)&&!state.bossWins?.['world_'+n.id])||worldNodes.find(n=>n.type==='boss'&&!state.bossWins?.['world_'+n.id])}
function bossPrep(n){if(!n)return'';const pull=getExercise('e3'),best=Math.max(0,...(pull?.history||[]).map(h=>Number(h.reps)||0),...(workoutEntry('e3')?.sets||[]).map(x=>Number(x.reps)||0));if(n.id==='cliffs')return best>=n.target?`Bereit: dein protokollierter Bestwert liegt bei ${best}.`:`Vorbereitung: Bestwert ${best||'noch keiner'} · Bossziel ${n.target}. Plane 2 Zug-Einheiten/Woche und teste erst bei guter Tagesform.`;return 'Gebietsboss: mehrere Fähigkeiten werden nacheinander geprüft.'}
function worldMap(){currentView='world';header();const p=worldProgress(),stats=charStats(),rec=recoveryScores();view.innerHTML=`<div class="sectiontitle"><div><h2>🗺️ Weltkarte</h2><div class="muted">Training bewegt deinen Helden – kein Tippen zum Grinden</div></div><span class="tag green">Fortschritt ${p}</span></div><div class="worldscene"><div class="worldfog"></div>${worldNodes.map((n,i)=>{const locked=!worldUnlocked(n),won=!!state.bossWins?.['world_'+n.id],current=i===unlockedWorldIndex();return `<button class="mapnode ${locked?'locked':''} ${current?'current':''} ${won?'won':''}" style="left:${n.x}%;top:${n.y}%" onclick="${locked?'lockedWorldNode()':`openWorldNode('${n.id}')`}"><span>${locked?'🌫️':won?'🏆':n.icon}</span><small>${locked?'???':n.name}</small></button>`}).join('')}<div class="maphero" style="left:${worldNodes[unlockedWorldIndex()].x}%;top:${Math.min(94,worldNodes[unlockedWorldIndex()].y+7)}%">🧙</div></div><div class="grid"><div class="card"><b>⚡ Charakterwerte</b>${Object.entries(stats).map(([k,v])=>`<div class="goalrow"><span>${k}</span><b>${v}</b></div>`).join('')}</div><div class="card"><b>💚 Erholung</b>${Object.entries(rec).slice(0,5).map(([k,v])=>`<div class="goalrow"><span>${k}</span><b>${v}%</b></div>`).join('')}</div></div><div class="custom-actions"><button class="btn secondary" onclick="openBase()">🏠 Basis</button><button class="btn secondary" onclick="openTrophyRoom()">🏆 Trophäenraum</button><button class="btn secondary" onclick="seasonCard()">📜 Season</button><button class="btn secondary" onclick="rpgSystemsHub()">🌳 Systeme</button><button class="btn secondary" onclick="readinessCheck()">❤️ Readiness</button></div><div class="notice">🌫️ Nebel des Krieges: Unbekannte Orte werden erst durch echte Workouts, Wissen und Boss-Siege sichtbar.</div>`}
window.worldMap=worldMap;window.lockedWorldNode=()=>toast('Dieser Teil der Karte liegt noch im Nebel 🌫️');
window.openWorldNode=id=>{const n=worldNodes.find(x=>x.id===id);if(!n)return;if(n.type==='boss')return openWorldBoss(id);if(n.type==='arena'){go('sport');return}if(n.type==='season')return seasonCard();modal(`<div class="celebrate">${n.icon}</div><h2>${n.name}</h2><p>${n.text||''}</p>${n.npc?`<button class="btn block" onclick="talkNPC('${n.npc}')">💬 Mit NPC sprechen</button>`:''}<button class="btn secondary block" onclick="closeModal()">Weiterreisen</button>`)};
const npcText={healer:['🧙 Heiler','Ruhetage sind Teil des Plans. Dein Fortschritt verfällt nicht, wenn das Leben dazwischenkommt.'],ranger:['🏹 Waldläufer','Beständigkeit schlägt hektisches Grinden. Ausdauer wächst über Wochen.'],smith:['⚒️ Schmied','Saubere Wiederholungen und progressive Steigerung schmieden Kraft.'],scholar:['🦉 Gelehrter','Knowledge Quests orientieren sich künftig stärker an deinem Training.'],monk:['🧘 Mönch','Skills brauchen Qualität. Ein sauberer Hold zählt mehr als ein erzwungener Rekord.']};
window.talkNPC=k=>{const t=npcText[k]||['NPC','Trainiere klug.'];modal(`<div class="celebrate">${t[0].split(' ')[0]}</div><h2>${t[0].slice(2)}</h2><p>${t[1]}</p><button class="btn block" onclick="closeModal()">Verstanden</button>`)};
window.openWorldBoss=id=>{const n=worldNodes.find(x=>x.id===id);modal(`<div class="celebrate">${n.icon}</div><h2>${n.name}</h2><p class="muted">BOSS FIGHT · Vorbereitung</p><div class="bosschallenge"><b>${n.challenge}</b><p>${bossPrep(n)}</p></div><label class="btn secondary block">🎥 Bosskampf filmen<input id="bossVideo" type="file" accept="video/*" capture="environment" style="display:none" onchange="bossVideoPicked(event,'${id}')"></label><div class="tiny">V0.10 markiert Videoaufnahmen als Beleg. Eine automatische KI-Zählung/Formbewertung wird nicht vorgetäuscht: dafür ist später ein getestetes Vision-Modul nötig.</div><button class="btn block" onclick="winWorldBoss('${id}','self')">✅ Leistung selbst bestätigt</button>`)};
window.bossVideoPicked=(ev,id)=>{const f=ev.target.files?.[0];if(!f)return;const n=worldNodes.find(x=>x.id===id);modal(`<h2>🎥 Video bereit</h2><p><b>${f.name}</b></p><video controls playsinline style="width:100%;border-radius:14px" src="${URL.createObjectURL(f)}"></video><div class="notice">Status: <b>Video-Beleg vorhanden</b>. Automatische Wiederholungs-/Technikprüfung ist noch nicht aktiv.</div><button class="btn block" onclick="winWorldBoss('${id}','video-evidence')">Bossleistung mit Video-Beleg speichern</button>`)};
window.winWorldBoss=(id,verified='self')=>{const n=worldNodes.find(x=>x.id===id);state.bossWins=state.bossWins||{};if(state.bossWins['world_'+id])return toast('Boss bereits besiegt 🏆');state.bossWins['world_'+id]={date:localDateKey(),verified};if(n.reward&&!state.world.loot.includes(n.reward))state.world.loot.push(n.reward);save();addXp(500,'BOSS FIGHT WON!');closeModal();worldMap()};
window.openBase=()=>{const w=(state.workoutHistory||[]).length,lvl=1+Math.floor(w/5);state.world.baseLevel=Math.max(state.world.baseLevel||1,lvl);save();modal(`<h2>🏠 Deine Basis · Stufe ${state.world.baseLevel}</h2><div class="basegrid"><div>🏋️<b>Trainingshalle</b><small>PRs & Pläne</small></div><div>📚<b>Bibliothek</b><small>Wissen ${state.knowledge?.xp||0} XP</small></div><div>🏆<b>Trophäenraum</b><small>${Object.keys(state.bossWins||{}).length} Bosse</small></div><div>⚒️<b>Schmiede</b><small>${state.world.loot.length} Loot</small></div></div><div class="tiny">Die Basis wächst automatisch mit absolvierten Workouts.</div>`)};
window.openTrophyRoom=()=>{const loot=state.world.loot||[],wins=Object.keys(state.bossWins||{}).length,mastered=skills.filter(x=>(state.skillProgress[x.id]||0)>=x.steps.length).length;modal(`<h2>🏆 Trophäenraum</h2><div class="grid"><div class="hero"><div class="kpi">${wins}</div><small>Bosse</small></div><div class="hero"><div class="kpi">${mastered}</div><small>Skills</small></div></div><h3>🎒 Loot</h3>${loot.length?loot.map(x=>`<div class="exercise"><span>✨ ${x}</span></div>`).join(''):'<div class="empty small">Noch kein Boss-Loot.</div>'}<div class="tiny">Loot ist rein kosmetisch und gibt keinen Trainingsvorteil.</div>`)};
window.seasonCard=()=>{if(!state.season.startedAt){state.season.startedAt=localDateKey();state.season.workoutsStart=state.workoutHistory.length;state.season.xpStart=state.xp;save()}const done=state.workoutHistory.length-(state.season.workoutsStart||0),xp=state.xp-(state.season.xpStart||0);modal(`<h2>📜 Season 1 · Aufbruch</h2><div class="hero"><div class="kpi">${done}</div><div class="muted">Workouts seit Season-Start</div></div><div class="goalrow"><span>XP gewonnen</span><b>+${Math.max(0,xp)}</b></div><div class="goalrow"><span>Bosse besiegt</span><b>${Object.keys(state.bossWins||{}).length}</b></div><div class="goalrow"><span>Loot</span><b>${state.world.loot.length}</b></div><p class="tiny">Eine Season ist eine Langzeit-Zusammenfassung; vorhandene Rekorde werden nicht zurückgesetzt.</p>`)};
function muscleLoad(){const out={Brust:0,Rücken:0,Beine:0,Schultern:0,Arme:0,Core:0,Gesäß:0};const cutoff=Date.now()-7*86400000;(state.workoutHistory||[]).forEach(w=>{if(new Date(w.finishedAt||w.date).getTime()<cutoff)return;(w.exercises||[]).forEach(x=>{const e=getExercise(x.id),g=(e?.group||'').toLowerCase(),sets=(x.sets||[]).length||Number(x.completed);let k=g.includes('brust')?'Brust':g.includes('rücken')?'Rücken':g.includes('bein')||g.includes('oberschenkel')||g.includes('waden')?'Beine':g.includes('schulter')?'Schultern':g.includes('bizeps')||g.includes('trizeps')||g.includes('unterarm')?'Arme':g.includes('bauch')||g.includes('core')?'Core':g.includes('gesäß')?'Gesäß':null;if(k)out[k]+=sets})});return out}
function recoveryDashboard(){const m=muscleLoad();modal(`<h2>🧠 Belastung · 7 Tage</h2>${Object.entries(m).map(([k,v])=>`<div class="goalrow"><span>${k}</span><b>${v} Sätze</b></div><div class="bar mini"><i style="width:${Math.min(100,v/16*100)}%"></i></div>`).join('')}<div class="tiny">Orientierung aus protokollierten Sätzen, keine medizinische Erholungsmessung.</div>`)}window.recoveryDashboard=recoveryDashboard;
window.betaFeedback=()=>modal(`<h2>🧪 Beta-Feedback</h2><div class="field"><label>Was war nervig, unklar oder fehlt?</label><textarea id="fbText" rows="5" placeholder="Kurz beschreiben …"></textarea></div><button class="btn block" onclick="saveFeedback()">Feedback lokal speichern</button><div class="tiny">Wird im Backup mitgesichert.</div>`);
window.saveFeedback=()=>{const t=$('#fbText').value.trim();if(!t)return;state.feedback=state.feedback||[];state.feedback.push({date:new Date().toISOString(),text:t});save();closeModal();toast('Feedback gespeichert 🧪')};

// V0.11 – deeper RPG systems. These systems are local-first and intentionally avoid pretending that camera/watch AI exists.
function bestPullups(){const h=(state.workoutHistory||[]).flatMap(w=>(w.exercises||[]).filter(x=>x.id==='e3').flatMap(x=>x.sets||[]));return Math.max(0,...h.map(x=>Number(x.reps)||0),...(workoutEntry('e3')?.sets||[]).map(x=>Number(x.reps)||0))}
function deriveClass(){const st=charStats();let name='Allrounder';if(st.Ausdauer>st.Kraft+8)name='Waldläufer';else if((state.settings.goal==='calisthenics'||st.Balance>st.Kraft+8))name='Mönch';else if(st.Kraft>st.Ausdauer+8)name='Krieger';state.rpgSystems.className=name;return name}
function masteryData(){const best=bestPullups();const tier=best>=20?'Platin':best>=15?'Gold':best>=10?'Silber':best>=5?'Bronze':'Novize';return {best,tier,next:best<5?5:best<10?10:best<15?15:best<20?20:null}}
function adaptiveBossTarget(){const b=bestPullups();return Math.max(5,b+Math.max(1,Math.ceil(b*.12)))}
function currentQuestChain(){const q=state.rpgSystems.questChain||{stage:0};const stages=['Basisvolumen sammeln','Technik & voller Bewegungsumfang','Explosive Zugkraft','Leichte Woche / Testvorbereitung','Bossversuch'];return {stage:q.stage||0,label:stages[Math.min(4,q.stage||0)],stages}}
window.advanceQuestChain=()=>{state.rpgSystems.questChain.stage=Math.min(4,(state.rpgSystems.questChain.stage||0)+1);save();rpgSystemsHub()}
function dynamicQuest(){const load=muscleLoad(),entries=Object.entries(load).sort((a,b)=>a[1]-b[1]);const [fresh,sets]=entries[0];return `${fresh} ist mit ${sets} protokollierten Sätzen in 7 Tagen aktuell am wenigsten belastet. Optionale Quest: ${fresh}-Einheit einplanen.`}
function periodizationText(){const p=state.rpgSystems.periodization||{week:1,phase:'Aufbau'};return p.week>=5?'Deload-Woche: Volumen bewusst reduzieren.':`Aufbauwoche ${p.week}/4: kontrolliert steigern, nicht jede Einheit bis ans Limit.`}
function whyCoachText(){const rec=recoveryScores(),low=Object.entries(rec).sort((a,b)=>b[1]-a[1])[0],high=Object.entries(rec).sort((a,b)=>a[1]-b[1])[0];return `Empfehlung basiert auf deinem protokollierten Verlauf: ${low[0]} wirkt mit ${low[1]}% relativ frisch; ${high[0]} liegt bei ${high[1]}%. ${periodizationText()}`}
window.coachWhy=()=>modal(`<h2>🔬 Warum?</h2><p>${whyCoachText()}</p><div class="tiny">Das ist eine Trainingsheuristik aus deinen Logs, keine medizinische Erholungsmessung.</div>`)
window.readinessCheck=()=>{const r=state.rpgSystems.readiness||{};modal(`<h2>❤️ Readiness</h2><p class="muted">Drei schnelle Angaben vor dem Training.</p><div class="field"><label>Schlaf 1–5</label><input id="rdSleep" type="range" min="1" max="5" value="${r.sleep||3}"></div><div class="field"><label>Energie 1–5</label><input id="rdEnergy" type="range" min="1" max="5" value="${r.energy||3}"></div><div class="field"><label>Muskelkater 0–4</label><input id="rdSore" type="range" min="0" max="4" value="${r.soreness||1}"></div><button class="btn block" onclick="saveReadinessV11()">Auswerten</button>`)}
window.saveReadinessV11=()=>{const sleep=+$('#rdSleep').value,energy=+$('#rdEnergy').value,soreness=+$('#rdSore').value;state.rpgSystems.readiness={date:localDateKey(),sleep,energy,soreness};save();const score=sleep+energy-soreness;const msg=score>=8?'🟢 Gute Tagesform – normal trainieren.':score>=5?'🟡 Mittel – sauber trainieren, Volumen bei Bedarf reduzieren.':'🔴 Schwach – Regeneration oder sehr leichte Einheit erwägen.';modal(`<h2>Readiness</h2><div class="notice">${msg}</div><button class="btn secondary block" onclick="coachWhy()">Warum?</button>`)}
window.skillTreeV11=()=>{const nodes=[['Klimmzug','Chest-to-Bar','Explosive Pull-up','Muscle-up'],['Wall Handstand','Freier Handstand','HSPU','One-Arm-Handstand'],['Tuck Sit','L-Sit','V-Sit','Press to Handstand']];modal(`<h2>🌳 Skill-Tree</h2>${nodes.map(r=>`<div class="card"><b>${r.join(' → ')}</b></div>`).join('')}<p class="tiny">Deine bestehenden Skillpfade liefern die Progressionsdaten; der Tree bündelt sie als RPG-Pfade.</p>`)}
window.masteryV11=()=>{const m=masteryData();modal(`<h2>⭐ Mastery</h2><div class="hero"><div class="kpi">${m.tier}</div><div>Klimmzüge · Bestwert ${m.best}</div></div>${m.next?`<p>Nächste Stufe bei ${m.next} sauberen Wiederholungen.</p>`:'<p>Platin erreicht.</p>'}<div class="tiny">Mastery nutzt protokollierte Leistungen und ersetzt keine Technikprüfung.</div>`)}
window.nemesisV11=()=>{const n=state.rpgSystems.nemesis.cliffs||{hp:1000,attempts:0};state.rpgSystems.nemesis.cliffs=n;save();modal(`<h2>👹 Nemesis · Bergwächter</h2><p>Boss-HP: <b>${n.hp}/1000</b> · Versuche: ${n.attempts}</p><p>Ein gescheiterter Versuch löscht nichts. Gültig selbst protokollierte Wiederholungen können Schaden verursachen.</p><div class="field"><label>Saubere Wiederholungen dieses Versuchs</label><input id="nemReps" type="number" min="0" max="50" value="${bestPullups()}"></div><button class="btn block" onclick="nemesisHit()">⚔️ Versuch speichern</button>`)}
window.nemesisHit=()=>{const reps=Math.max(0,+$('#nemReps').value||0),n=state.rpgSystems.nemesis.cliffs||{hp:1000,attempts:0};n.attempts++;n.hp=Math.max(0,n.hp-reps*40);state.rpgSystems.nemesis.cliffs=n;save();if(!n.hp){addXp(500,'Nemesis besiegt');achievementPop('BOSS FIGHT WON!','Nemesis besiegt','boss')}nemesisV11()}
window.petV11=()=>{const opts=[['🐺','Wolf','Ausdauer'],['🐻','Bär','Kraft'],['🦅','Falke','Skills']];modal(`<h2>🐾 Begleiter</h2><p>Rein kosmetisch – keine Trainingsboni.</p>${opts.map(([i,n,t])=>`<button class="btn secondary block" onclick="choosePet('${i} ${n}')">${i} ${n} · ${t}</button>`).join('')}`)}
window.choosePet=p=>{state.rpgSystems.pet=p;save();closeModal();toast(`${p} begleitet dich jetzt`)}
window.coachMemoryV11=()=>modal(`<h2>📝 Coach-Gedächtnis</h2><p class="muted">Regeln bleiben lokal und können gelöscht werden.</p>${(state.rpgSystems.coachRules||[]).map((x,i)=>`<div class="exercise"><span>${x}</span><button class="iconbtn" onclick="deleteCoachRule(${i})">✕</button></div>`).join('')}<div class="field"><input id="coachRule" placeholder="z. B. montags nur 30 Minuten"></div><button class="btn block" onclick="addCoachRule()">Regel merken</button>`)
window.addCoachRule=()=>{const v=$('#coachRule').value.trim();if(v){state.rpgSystems.coachRules.push(v);save();coachMemoryV11()}};window.deleteCoachRule=i=>{state.rpgSystems.coachRules.splice(i,1);save();coachMemoryV11()}
window.shadowBossV11=()=>{const sh=state.rpgSystems.shadow;if(!sh.startedAt){sh.startedAt=localDateKey();sh.snapshot={pullups:bestPullups(),level:state.level,xp:state.xp};save()}const now=bestPullups(),old=sh.snapshot.pullups||0;modal(`<h2>🌑 Shadow Boss</h2><p>Season-Schatten vom ${sh.startedAt}</p><div class="goalrow"><span>Damals Klimmzüge</span><b>${old}</b></div><div class="goalrow"><span>Heute</span><b>${now}</b></div><div class="notice">${now>old?'🏆 Dein heutiges Ich liegt vorn.':'⚔️ Dein Schatten wartet noch.'}</div>`)}
window.guildV11=()=>modal(`<h2>🏰 Private Gilde</h2><div class="field"><label>Gildenname</label><input id="guildName" value="${state.rpgSystems.guild.name||''}" placeholder="z. B. Eisenbund"></div><button class="btn block" onclick="saveGuildV11()">Lokal anlegen</button><p class="tiny">V0.11 speichert die Gilde lokal. Echte Freunde/Cloud-Synchronisierung benötigt später einen Account-/Serverdienst.</p>`);window.saveGuildV11=()=>{state.rpgSystems.guild.name=$('#guildName').value.trim();save();closeModal();toast('Gilde gespeichert')}
window.labsV11=()=>modal(`<h2>🧪 Hardware & Vision Labs</h2><div class="card"><b>🎥 Auto-Workout / KI-Formcheck</b><p>Workflow vorbereitet: Video → Wiederholungen → ROM/Technikkriterien → Replay. Noch nicht als automatische Prüfung aktiv, solange kein getestetes Vision-Modul eingebunden ist.</p></div><div class="card"><b>⌚ Wear OS / Galaxy Watch</b><p>Integrationsziel: Puls, Dauer, Schritte und Satzsteuerung. Eine reine Web-PWA kann nicht dieselbe native Sensorintegration garantieren wie eine Android-/Wear-OS-App.</p></div><div class="card"><b>🎥 Ghost Replay</b><p>Wird mit der Videoanalyse gekoppelt, damit alte und neue Versuche vergleichbar werden.</p></div>`)
window.rpgSystemsHub=()=>{const m=masteryData(),q=currentQuestChain(),klass=deriveClass();save();modal(`<h2>🌳 RPG-Systeme</h2><div class="hero"><div class="kpi">${klass}</div><div class="muted">Deine Klasse entsteht aus deinem echten Training.</div>${state.rpgSystems.pet?`<p>${state.rpgSystems.pet} begleitet dich.</p>`:''}</div><div class="card"><b>🧭 Dynamische Quest</b><p>${dynamicQuest()}</p></div><div class="card"><b>🧩 Questkette: ${q.label}</b><p>Stufe ${q.stage+1}/5 · Ziel: ${state.rpgSystems.questChain.goal}</p><button class="btn secondary" onclick="advanceQuestChain()">Nächste Phase</button></div><div class="card"><b>🎯 Adaptiver Boss</b><p>Aktueller Klimmzug-Bestwert: ${m.best}. Nächstes Bossziel: <b>${adaptiveBossTarget()}</b>.</p></div><div class="card"><b>📅 Periodisierung</b><p>${periodizationText()}</p></div><div class="custom-actions"><button class="btn secondary" onclick="skillTreeV11()">🌳 Skill-Tree</button><button class="btn secondary" onclick="masteryV11()">⭐ Mastery</button><button class="btn secondary" onclick="nemesisV11()">👹 Nemesis</button><button class="btn secondary" onclick="petV11()">🐾 Begleiter</button><button class="btn secondary" onclick="shadowBossV11()">🌑 Shadow</button><button class="btn secondary" onclick="coachMemoryV11()">📝 Coach-Regeln</button><button class="btn secondary" onclick="guildV11()">🏰 Gilde</button><button class="btn secondary" onclick="labsV11()">🧪 Vision/Watch Labs</button><button class="btn secondary" onclick="coachWhy()">🔬 Warum?</button></div>`)}

function onboarding(){const y=new Date().getFullYear();modal(`<div class="celebrate">🧙</div><h2>Charakter erstellen</h2><p class="muted">1–2 Minuten. Daraus baut Workout RPG deinen ersten Coach-Wochenplan.</p><div class="formgrid"><div class="grid"><div class="field"><label>Geburtsjahr</label><input id="obBirth" inputmode="numeric" value="${state.settings.birthYear||''}" placeholder="z. B. 1988"></div><div class="field"><label>Geschlecht / DOSB-Tabelle</label><select id="obSex"><option value="">wählen</option><option value="male" ${state.settings.sex==='male'?'selected':''}>männlich</option><option value="female" ${state.settings.sex==='female'?'selected':''}>weiblich</option></select></div></div><div class="grid"><div class="field"><label>Gewicht (kg)</label><input id="obWeight" inputmode="decimal" value="${state.settings.bodyWeightKg||''}"></div><div class="field"><label>Größe (cm)</label><input id="obHeight" inputmode="numeric" value="${state.settings.bodyHeightCm||''}"></div></div><div class="field"><label>Ziel</label><select id="obGoal"><option value="muscle">Muskelaufbau</option><option value="strength">Kraft</option><option value="allround">Allround</option><option value="calisthenics">Calisthenics</option></select></div><div class="grid"><div class="field"><label>Trainingstage/Woche</label><select id="obDays"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></div><div class="field"><label>Zeit/Einheit</label><select id="obMinutes"><option>20</option><option>30</option><option selected>45</option><option>60</option></select></div></div><div class="field"><label>Erfahrung</label><select id="obExp"><option value="beginner">Einsteiger</option><option value="returning" selected>Wiedereinstieg</option><option value="advanced">Fortgeschritten</option></select></div><h3>Equipment</h3>${Object.entries({pullup:'Klimmzugstange',bench:'Bank',dumbbell:'Kurzhanteln',bands:'Bänder',barbell:'Langhantel',rack:'Rack',rings:'Ringe',dips:'Dip-Barren'}).map(([k,n])=>`<label class="exercise"><span>${n}</span><input type="checkbox" id="ob_${k}" ${state.equipment[k]?'checked':''}></label>`).join('')}<button class="btn block" onclick="finishOnboarding()">⚔️ Workout RPG starten</button></div>`)}
window.finishOnboarding=()=>{state.settings.birthYear=$('#obBirth').value;state.settings.sex=$('#obSex').value;state.settings.bodyWeightKg=$('#obWeight').value;state.settings.bodyHeightCm=$('#obHeight').value;state.settings.goal=$('#obGoal').value;state.settings.trainingDays=Number($('#obDays').value)||3;state.settings.sessionMinutes=Number($('#obMinutes').value)||45;state.settings.experience=$('#obExp').value;for(const k of Object.keys(state.equipment)){const el=$('#ob_'+k);if(el)state.equipment[k]=el.checked}state.settings.onboardingComplete=true;state.inactivity.lastTrainingDate=localDateKey();state.inactivity.appliedPeriods=0;generateCoachPlan();save();closeModal();home();setTimeout(()=>showCoachPlan(),150)}

function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')};window.closeModal=closeModal;
function go(v){currentView=v;header();if(v==='home')home();if(v==='training')training();if(v==='skills')skillsView();if(v==='body')body();if(v==='sport')sportBadge();if(v==='progress')progress();if(v==='world')worldMap()};window.go=go;
document.querySelectorAll('.bottomnav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#closeModal').onclick=closeModal;$('#settingsBtn').onclick=settings;
$('#todayLabel').textContent=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'2-digit'}).format(new Date());
ensureDailyReset();scheduleMidnightReset();scheduleStepReminder();initInactivityAnchor();checkInactivityPenalty(true);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
go('home');if(!state.settings.onboardingComplete)setTimeout(onboarding,180);
